use split_decls_genesis :: ourprelude :: * ; use rustc_data_structures :: fx :: FxHashSet ; use rustc_middle :: bug ; use rustc_middle :: ty :: { self , Ty , TyCtxt , TypeFoldable , TypeSuperVisitable , TypeVisitor } ; use rustc_span :: Span ; use tracing :: debug ; #[derive (Clone , PartialEq , Eq , Hash , Debug)] pub (crate) struct Parameter (pub u32) ; impl From < ty :: ParamTy > for Parameter { fn from (param : ty :: ParamTy) -> Self { Parameter (param . index) } } impl From < ty :: EarlyParamRegion > for Parameter { fn from (param : ty :: EarlyParamRegion) -> Self { Parameter (param . index) } } impl From < ty :: ParamConst > for Parameter { fn from (param : ty :: ParamConst) -> Self { Parameter (param . index) } } #[doc = " Returns the set of parameters constrained by the impl header."] pub (crate) fn parameters_for_impl < 'tcx > (tcx : TyCtxt < 'tcx > , impl_self_ty : Ty < 'tcx > , impl_trait_ref : Option < ty :: TraitRef < 'tcx > > ,) -> FxHashSet < Parameter > { let vec = match impl_trait_ref { Some (tr) => parameters_for (tcx , tr , false) , None => parameters_for (tcx , impl_self_ty , false) , } ; vec . into_iter () . collect () } #[doc = " If `include_nonconstraining` is false, returns the list of parameters that are"] #[doc = " constrained by `value` - i.e., the value of each parameter in the list is"] #[doc = " uniquely determined by `value` (see RFC 447). If it is true, return the list"] #[doc = " of parameters whose values are needed in order to constrain `value` - these"] #[doc = " differ, with the latter being a superset, in the presence of projections."] pub (crate) fn parameters_for < 'tcx > (tcx : TyCtxt < 'tcx > , value : impl TypeFoldable < TyCtxt < 'tcx > > , include_nonconstraining : bool ,) -> Vec < Parameter > { let mut collector = ParameterCollector { parameters : vec ! [] , include_nonconstraining } ; let value = if ! include_nonconstraining { tcx . expand_free_alias_tys (value) } else { value } ; value . visit_with (& mut collector) ; collector . parameters } struct ParameterCollector { parameters : Vec < Parameter > , include_nonconstraining : bool , } impl < 'tcx > TypeVisitor < TyCtxt < 'tcx > > for ParameterCollector { fn visit_ty (& mut self , t : Ty < 'tcx >) { match * t . kind () { ty :: Alias (ty :: Projection | ty :: Inherent | ty :: Opaque , _) if ! self . include_nonconstraining => { return ; } ty :: Alias (ty :: Free , _) if ! self . include_nonconstraining => { bug ! ("unexpected free alias type") } ty :: Param (param) => self . parameters . push (Parameter :: from (param)) , _ => { } } t . super_visit_with (self) } fn visit_region (& mut self , r : ty :: Region < 'tcx >) { if let ty :: ReEarlyParam (data) = r . kind () { self . parameters . push (Parameter :: from (data)) ; } } fn visit_const (& mut self , c : ty :: Const < 'tcx >) { match c . kind () { ty :: ConstKind :: Unevaluated (..) if ! self . include_nonconstraining => { return ; } ty :: ConstKind :: Param (data) => { self . parameters . push (Parameter :: from (data)) ; } _ => { } } c . super_visit_with (self) } } pub (crate) fn identify_constrained_generic_params < 'tcx > (tcx : TyCtxt < 'tcx > , predicates : ty :: GenericPredicates < 'tcx > , impl_trait_ref : Option < ty :: TraitRef < 'tcx > > , input_parameters : & mut FxHashSet < Parameter > ,) { let mut predicates = predicates . predicates . to_vec () ; setup_constraining_predicates (tcx , & mut predicates , impl_trait_ref , input_parameters) ; } #[doc = " Order the predicates in `predicates` such that each parameter is"] #[doc = " constrained before it is used, if that is possible, and add the"] #[doc = " parameters so constrained to `input_parameters`. For example,"] #[doc = " imagine the following impl:"] #[doc = " ```ignore (illustrative)"] #[doc = " impl<T: Debug, U: Iterator<Item = T>> Trait for U"] #[doc = " ```"] #[doc = " The impl's predicates are collected from left to right. Ignoring"] #[doc = " the implicit `Sized` bounds, these are"] #[doc = "   * `T: Debug`"] #[doc = "   * `U: Iterator`"] #[doc = "   * `<U as Iterator>::Item = T` -- a desugared ProjectionPredicate"] #[doc = ""] #[doc = " When we, for example, try to go over the trait-reference"] #[doc = " `IntoIter<u32> as Trait`, we instantiate the impl parameters with fresh"] #[doc = " variables and match them with the impl trait-ref, so we know that"] #[doc = " `$U = IntoIter<u32>`."] #[doc = ""] #[doc = " However, in order to process the `$T: Debug` predicate, we must first"] #[doc = " know the value of `$T` - which is only given by processing the"] #[doc = " projection. As we occasionally want to process predicates in a single"] #[doc = " pass, we want the projection to come first. In fact, as projections"] #[doc = " can (acyclically) depend on one another - see RFC447 for details - we"] #[doc = " need to topologically sort them."] #[doc = ""] #[doc = " We *do* have to be somewhat careful when projection targets contain"] #[doc = " projections themselves, for example in"] #[doc = ""] #[doc = " ```ignore (illustrative)"] #[doc = "     impl<S,U,V,W> Trait for U where"] #[doc = " /* 0 */   S: Iterator<Item = U>,"] #[doc = " /* - */   U: Iterator,"] #[doc = " /* 1 */   <U as Iterator>::Item: ToOwned<Owned=(W,<V as Iterator>::Item)>"] #[doc = " /* 2 */   W: Iterator<Item = V>"] #[doc = " /* 3 */   V: Debug"] #[doc = " ```"] #[doc = ""] #[doc = " we have to evaluate the projections in the order I wrote them:"] #[doc = " `V: Debug` requires `V` to be evaluated. The only projection that"] #[doc = " *determines* `V` is 2 (1 contains it, but *does not determine it*,"] #[doc = " as it is only contained within a projection), but that requires `W`"] #[doc = " which is determined by 1, which requires `U`, that is determined"] #[doc = " by 0. I should probably pick a less tangled example, but I can't"] #[doc = " think of any."] pub (crate) fn setup_constraining_predicates < 'tcx > (tcx : TyCtxt < 'tcx > , predicates : & mut [(ty :: Clause < 'tcx > , Span)] , impl_trait_ref : Option < ty :: TraitRef < 'tcx > > , input_parameters : & mut FxHashSet < Parameter > ,) { debug ! ("setup_constraining_predicates: predicates={:?} \
            impl_trait_ref={:?} input_parameters={:?}" , predicates , impl_trait_ref , input_parameters) ; let mut i = 0 ; let mut changed = true ; while changed { changed = false ; for j in i .. predicates . len () { if let ty :: ClauseKind :: Projection (projection) = predicates [j] . 0 . kind () . skip_binder () { let unbound_trait_ref = projection . projection_term . trait_ref (tcx) ; if Some (unbound_trait_ref) == impl_trait_ref { continue ; } let inputs = parameters_for (tcx , projection . projection_term , true) ; let relies_only_on_inputs = inputs . iter () . all (| p | input_parameters . contains (p)) ; if ! relies_only_on_inputs { continue ; } input_parameters . extend (parameters_for (tcx , projection . term , false)) ; } else { continue ; } predicates . swap (i , j) ; i += 1 ; changed = true ; } debug ! ("setup_constraining_predicates: predicates={:?} \
                i={} impl_trait_ref={:?} input_parameters={:?}" , predicates , i , impl_trait_ref , input_parameters) ; } }